  let state = null;

  function onPointerMove(e) {
    if (!state) return;
    e.preventDefault();
    const y = e.clientY;
    state.li.style.top = (y - state.offY) + 'px';
    if (!state.moved && Math.abs(y - state.lastY) > 3) state.moved = true;
    updateDropPosition(y);
  }

  function updateDropPosition(y) {
    const ul = state.ul;
    const sib = Array.from(ul.children).filter(el => el !== state.li);
    state.li.style.visibility = 'hidden';
    let target = null, pos = null; // pos: 'before' | 'after'
    for (const s of sib) {
      const r = s.getBoundingClientRect();
      if (y < r.top + r.height / 2) { target = s; pos = 'before'; break; }
      target = s; pos = 'after';
    }
    if (target) {
      if (pos === 'before') ul.insertBefore(state.li, target);
      else ul.insertBefore(state.li, target.nextSibling);
    } else {
      ul.appendChild(state.li);
    }
    state.li.style.visibility = '';
  }

  function onPointerUp(e) {
    window.removeEventListener('pointermove', onPointerMove, { passive: false });
    window.removeEventListener('pointerup', onPointerUp);
    window.removeEventListener('pointercancel', onPointerCancel);
    finalizeDrag(false);
  }
  function onPointerCancel(e) {
    window.removeEventListener('pointermove', onPointerMove, { passive: false });
    window.removeEventListener('pointerup', onPointerUp);
    window.removeEventListener('pointercancel', onPointerCancel);
    finalizeDrag(true);
  }

  function finalizeDrag(cancelled) {
    if (!state) return;
    const s = state;
    state = null;
    s.li.classList.remove('is-dragging');
    s.li.style.position = '';
    s.li.style.left = '';
    s.li.style.top = '';
    s.li.style.width = '';
    s.li.style.margin = '';
    s.li.style.zIndex = '';
    s.li.style.boxShadow = '';
    // If user didn't actually move, we already kept the item; nothing to do.
    // Data arrays are updated by DOM order on collect.
  }

  // =========================
  // scoring (as in original: pos 0 = major, pos 3 = minor)
  // =========================
  const collectPayload = () => {
    const payload = [];
    STEPS.forEach((cards, si) => {
      const pane = body.querySelector('.dsc-pane[data-step="' + si + '"]');
      const uls = pane ? Array.from(pane.querySelectorAll('.dsc-list')) : [];
      uls.forEach((ul) => {
        Array.from(ul.querySelectorAll('li')).forEach(li => {
          const data = cards.find(it => it.t === li.textContent && it.type);
          payload.push({ type: li._discType || (data && data.type) || 'd' });
        });
      });
    });
    return payload;
  };

  const score = (payload) => {
    const maj = [], min = [];
    payload.forEach((x, i) => {
      const posInList = i % 4;
      if (posInList === 0) maj.push(x.type);
      if (posInList === 3) min.push(x.type);
    });
    const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
    return {
      D: count(maj, 'd') - count(min, 'd'),
      I: count(maj, 'i') - count(min, 'i'),
      S: count(maj, 's') - count(min, 's'),
      C: count(maj, 'c') - count(min, 'c')
    };
  };

  // tag each li with its type for fast collection
  const tagType = (li, data) => { li._discType = data.type; };
  body.querySelectorAll('.dsc-list > li').forEach(li => {
    // already tagged via bindItem — re-tag for safety:
    // use data attr stored at build time below
  });

  // actually: we'll rebuild _discType on collect via lookup against STEPS. Simpler:
  // override collectPayload to use data attr.
  STEPS.forEach((cards, si) => {
    const pane = body.querySelector('.dsc-pane[data-step="' + si + '"]');
    if (!pane) return;
    const uls = Array.from(pane.querySelectorAll('.dsc-list'));
    uls.forEach((ul, ci) => {
      Array.from(ul.children).forEach((li, liIdx) => {
        const data = cards[ci * 4 + liIdx];
        li.dataset.discType = data.type;
      });
    });
  });

  const collectPayloadDom = () => {
    const payload = [];
    STEPS.forEach((_, si) => {
      const pane = body.querySelector('.dsc-pane[data-step="' + si + '"]');
      if (!pane) return;
      Array.from(pane.querySelectorAll('.dsc-list > li')).forEach(li => {
        payload.push({ type: li.dataset.discType || 'd' });
      });
    });
    return payload;
  };

  // =========================
  // show result
  // =========================
  const K = {
    D: { label: 'Д — Доминирование', key: 'D' },
    I: { label: 'И — Влияние', key: 'I' },
    S: { label: 'С — Стабильность', key: 'S' },
    C: { label: 'С — Соответствие', key: 'C' }
  };

  const showResult = () => {
    const s = score(collectPayloadDom());

    scoreLine.innerHTML =
      '<div class="dsc-score">D: ' + s.D + ' &nbsp;·&nbsp; I: ' + s.I +
      ' &nbsp;·&nbsp; S: ' + s.S + ' &nbsp;·&nbsp; C: ' + s.C + '</div>';

    const rows = [
      ['D', s.D], ['I', s.I], ['S', s.S], ['C', s.C]
    ];
    barsBlock.innerHTML = rows.map(([k, v]) => {
      // map value in [-4, 4] -> width in [12, 100]%
      const norm = (v + 4) / 8; // 0..1
      const pct = Math.max(6, Math.round(12 + norm * 88));
      return (
        '<div class="dsc-bars__item">' +
          '<div class="dsc-bars__label"><b>' + k + ' — ' +
            ({D:'Доминирование', I:'Влияние', S:'Стабильность', C:'Соответствие'}[k] || '') +
          '</b><span>' + v + '</span></div>' +
          '<div class="dsc-bars__track"><div class="dsc-bars__fill" style="width:' + pct + '%"></div></div>' +
        '</div>'
      );
    }).join('');

    // switch UI to result
    step = TOTAL_STEPS; // sentinel
    tabs.forEach(t => { t.classList.remove('is-active'); t.setAttribute('aria-selected', 'false'); });
    tabsBlock.style.display = 'none';
    body.querySelectorAll('.dsc-pane[data-step]').forEach(p => p.classList.remove('is-active'));
    paneLanding.classList.remove('is-active');
    paneResult.classList.add('is-active');
    headTitle.textContent = 'Результат';
    headSub.textContent   = 'Ваш DISC-профиль';
    headLead.textContent  = 'Ниже — ваши баллы по четырём поведенческим стилям.';
    prevBtn.disabled = true;
    nextBtn.hidden = true;
    finishBtn.hidden = true;
    progressBar.style.width = '100%';
    body.scrollTop = 0;
  };

  // =========================
  // nav wiring
  // =========================
  startBtn.addEventListener('click', () => setStep(0));

  prevBtn.addEventListener('click', () => { if (step > 0) setStep(step - 1); else if (step === -1) {} });
  nextBtn.addEventListener('click', () => { if (step >= 0 && step < TOTAL_STEPS - 1) setStep(step + 1); });
  finishBtn.addEventListener('click', () => showResult());

  const restart = () => {
    // reset drag states
    body.querySelectorAll('.dsc-item').forEach(li => {
      li.classList.remove('is-dragging', 'is-over');
      li.style.cssText = '';
    });
    // reset order in DOM: rebuild list order based on original STEPS
    STEPS.forEach((cards, si) => {
      const pane = body.querySelector('.dsc-pane[data-step="' + si + '"]');
      if (!pane) return;
      const uls = Array.from(pane.querySelectorAll('.dsc-list'));
      uls.forEach((ul, ci) => {
        const desired = cards.slice(ci * 4, ci * 4 + 4).map(d => d.t);
        const byText = {};
        Array.from(ul.children).forEach(li => { byText[li.textContent] = li; });
        desired.forEach(t => ul.appendChild(byText[t]));
      });
    });
    // reset header & panes
    headTitle.textContent = 'Тестирование DISC';
    headSub.textContent   = 'Помните — чем честнее вы с тестом, тем точнее результаты!';
    headLead.textContent  = 'Разместите блоки в порядке от наиболее похожего на вас до наименее похожего';
    paneResult.classList.remove('is-active');
    paneLanding.classList.add('is-active');
    step = -1;
    render();
  };
  restartBtn.addEventListener('click', restart);

  // initial state
  modal.classList.add('is-open');
  modal.setAttribute('aria-hidden', 'false');
  syncScrollLock();
  render();
})();
</script>
</body>
