// =========================
// scoring (as in original: pos 0 = major, pos 3 = minor)
// =========================
const score = (payload) => {
  const maj = [], min = [];
  payload.forEach((x, i) => {
    const posInList = i % 4;
    if (posInList === 0) maj.push(x.type);
    if (posInList === 3) min.push(x.type);
  });
  const count = (arr, ch) => arr.reduce((a, v) => a + (v === ch ? 1 : 0), 0);
  return {
    D: count(maj, 'd') - count(min, 'd'),
    I: count(maj, 'i') - count(min, 'i'),
    S: count(maj, 's') - count(min, 's'),
    C: count(maj, 'c') - count(min, 'c')
  };
};

// tag each li with its DISC type at build time (for fast collection)
STEPS.forEach((cards, si) => {
  const pane = body.querySelector('.dsc-pane[data-step="' + si + '"]');
  if (!pane) return;
  Array.from(pane.querySelectorAll('.dsc-list > li')).forEach((li, idx) => {
    li.dataset.discType = cards[idx].type;
  });
});

const collectPayloadDom = () => {
  const payload = [];
  STEPS.forEach((_, si) => {
    const pane = body.querySelector('.dsc-pane[data-step="' + si + '"]');
    if (!pane) return;
    Array.from(pane.querySelectorAll('.dsc-list > li')).forEach(li => {
      payload.push({ type: li.dataset.discType || 'd' });
    });
  });
  return payload;
};

